/**
 * Sync published GitHub Issues into content.json.
 *
 * Rules:
 *   - Issue with label `blog`, open, and without label `draft` => published post.
 *   - Closing the issue or adding `draft` => post is removed from the site.
 *   - Title -> post title, body -> Markdown article body.
 *   - Optional first line `slug: my-custom-slug` overrides the URL slug.
 *   - Posts not generated by Issues (no issueNumber field) are preserved.
 */
import fs from 'node:fs';
import path from 'node:path';

const repo = process.env.GITHUB_REPOSITORY;
const token = process.env.GITHUB_TOKEN;
const api = (process.env.GITHUB_API_URL || 'https://api.github.com').replace(/\/$/, '');
const contentPath = path.resolve(process.cwd(), 'content.json');

if (!repo || !token) {
  console.error('GITHUB_REPOSITORY and GITHUB_TOKEN are required.');
  process.exit(1);
}

function labelNames(issue) {
  return (issue.labels || []).map(function (l) {
    return typeof l === 'string' ? l : l.name;
  }).map(function (n) { return String(n || '').toLowerCase(); });
}

function readingMinutes(body) {
  const text = String(body || '');
  const cjk = (text.match(/[\u3400-\u9fff]/g) || []).length;
  const words = (text.replace(/[\u3400-\u9fff]/g, ' ').match(/[A-Za-z0-9]+/g) || []).length;
  return Math.max(1, Math.round(cjk / 400 + words / 200));
}

function toPost(issue) {
  let body = String(issue.body || '').replace(/\r\n?/g, '\n').trim();
  const slugMatch = body.match(/^\s*slug:\s*([a-z0-9][a-z0-9-]{0,60})\s*(?:\n|$)/i);
  const slug = slugMatch ? slugMatch[1].toLowerCase() : 'issue-' + issue.number;
  if (slugMatch) body = body.slice(slugMatch[0].length).trim();

  return {
    slug: slug,
    title: String(issue.title || 'Untitled').trim(),
    date: String(issue.created_at || '').slice(0, 10) + ' · ' + readingMinutes(body) + ' min read',
    body: body,
    issueNumber: issue.number,
    issueUrl: issue.html_url
  };
}

async function fetchIssues() {
  const all = [];
  for (let page = 1; page <= 10; page += 1) {
    const url = api + '/repos/' + repo + '/issues?state=all&labels=blog'
      + '&sort=created&direction=desc&per_page=100&page=' + page;
    const res = await fetch(url, {
      headers: {
        'Accept': 'application/vnd.github+json',
        'Authorization': 'Bearer ' + token,
        'User-Agent': 'issues-to-blog'
      }
    });
    if (!res.ok) throw new Error('GitHub API ' + res.status + ': ' + (await res.text()).slice(0, 200));
    const items = await res.json();
    all.push(...items.filter(function (i) { return !i.pull_request; }));
    if (items.length < 100) break;
  }
  return all;
}

const data = JSON.parse(fs.readFileSync(contentPath, 'utf8'));
const issues = await fetchIssues();
const published = issues
  .filter(function (i) {
    const labels = labelNames(i);
    return i.state === 'open' && labels.includes('blog') && !labels.includes('draft');
  })
  .map(toPost);

const manual = (data.writings || []).filter(function (w) { return !w.issueNumber; });
data.writings = published.concat(manual);
fs.writeFileSync(contentPath, JSON.stringify(data, null, 2) + '\n');

console.log('Published from Issues: ' + published.length + ', kept manual posts: ' + manual.length);
published.forEach(function (p) { console.log('  - #' + p.issueNumber + ' ' + p.title + ' -> ' + p.slug); });
